async def act(page):
    """
    Navigate to the Sales > Orders grid, filter to cancelled orders if a Status combobox
    is present, then print exactly the date text for the most-recent cancelled order
    (the top data row after filtering). If no date can be determined, print an empty string.
    """
    # Navigate to the Sales Orders grid using a relative URL
    await page.goto('/index.php/admin/sales_order/index/')

    # Allow the page and grid to render
    await page.wait_for_timeout(800)

    # Scan all comboboxes for an option that contains 'cancel' (case-insensitive)
    comboboxes = page.get_by_role('combobox')
    try:
        n_comboboxes = await comboboxes.count()
    except Exception:
        n_comboboxes = 0

    status_select = None
    cancel_label = None
    for i in range(n_comboboxes):
        sel = comboboxes.nth(i)
        try:
            opts = sel.get_by_role('option')
            option_texts = await opts.all_inner_texts()
        except Exception:
            option_texts = []
        for opt in option_texts:
            if opt and 'cancel' in opt.lower():
                status_select = sel
                cancel_label = opt
                break
        if status_select:
            break

    # If found, select by the exact DOM-visible label
    if status_select and cancel_label:
        try:
            await status_select.select_option(label=cancel_label)
        except Exception:
            # Narrow fallbacks for common variants
            for candidate in ('Cancelled', 'Canceled', 'cancelled', 'canceled'):
                try:
                    await status_select.select_option(label=candidate)
                    cancel_label = candidate
                    break
                except Exception:
                    pass

    # Apply the filter by clicking the Search button if it exists
    search_btn = page.get_by_role('button', name='Search')
    try:
        if await search_btn.count() > 0:
            await search_btn.first().click()
        else:
            await page.wait_for_timeout(1000)
    except Exception:
        await page.wait_for_timeout(1000)

    # Wait for the results to populate
    await page.wait_for_timeout(900)

    # Locate tables and choose the one that looks like the orders grid (has a date-like header)
    tables = page.get_by_role('table')
    try:
        n_tables = await tables.count()
    except Exception:
        n_tables = 0

    chosen_table = None
    for i in range(n_tables):
        tbl = tables.nth(i)
        try:
            rows = tbl.get_by_role('row')
            if await rows.count() == 0:
                continue
            header = rows.nth(0)
            header_cells = header.get_by_role('columnheader')
            if await header_cells.count() == 0:
                header_cells = header.get_by_role('cell')

            try:
                n_header_cells = await header_cells.count()
            except Exception:
                n_header_cells = 0

            found_date_header = False
            for j in range(n_header_cells):
                try:
                    htxt = (await header_cells.nth(j).inner_text() or '').strip().lower()
                except Exception:
                    htxt = ''
                if any(k in htxt for k in ('purchas', 'purchase', 'date', 'ordered', 'created')):
                    found_date_header = True
                    break
            if found_date_header:
                chosen_table = tbl
                break
        except Exception:
            continue

    # Fallback to first table if none matched heuristically
    if chosen_table is None and n_tables > 0:
        chosen_table = tables.first()

    if chosen_table is None:
        print('')
        return

    # Get rows from chosen table
    rows = chosen_table.get_by_role('row')
    try:
        n_rows = await rows.count()
    except Exception:
        n_rows = 0

    # Need at least one data row (header + data)
    if n_rows < 2:
        print('')
        return

    # Determine purchase/date column index from header
    header_row = rows.nth(0)
    header_cells = header_row.get_by_role('columnheader')
    if await header_cells.count() == 0:
        header_cells = header_row.get_by_role('cell')

    try:
        n_header_cells = await header_cells.count()
    except Exception:
        n_header_cells = 0

    purchase_col_index = None
    for i in range(n_header_cells):
        try:
            txt = (await header_cells.nth(i).inner_text() or '').strip().lower()
        except Exception:
            txt = ''
        if any(k in txt for k in ('purchas', 'purchase', 'date', 'ordered', 'created')):
            purchase_col_index = i
            break

    # If not found via header, use heuristics on the first data row
    first_data_row = rows.nth(1)
    data_cells = first_data_row.get_by_role('cell')
    try:
        n_data_cells = await data_cells.count()
    except Exception:
        n_data_cells = 0

    if purchase_col_index is None:
        for guess in range(min(6, max(3, n_data_cells))):
            if guess >= n_data_cells:
                continue
            try:
                candidate = (await data_cells.nth(guess).inner_text() or '').strip()
            except Exception:
                candidate = ''
            if any(ch.isdigit() for ch in candidate) and len(candidate) >= 6:
                purchase_col_index = guess
                break

    if purchase_col_index is None:
        print('')
        return

    # Ensure index is in range and retrieve the date
    if purchase_col_index >= n_data_cells:
        try:
            fallback_text = (await first_data_row.inner_text() or '').strip()
        except Exception:
            fallback_text = ''
        print(fallback_text)
        return

    try:
        date_text = (await data_cells.nth(purchase_col_index).inner_text() or '').strip()
    except Exception:
        date_text = ''

    # Print exactly the date text (or empty string)
    print(date_text)

